-- Anvi Mitra ERP base schema. Shared tables required by extension migrations.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS schools(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),name VARCHAR(200) NOT NULL,code VARCHAR(80) NOT NULL UNIQUE,status VARCHAR(20) NOT NULL DEFAULT 'active',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS branches(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),school_id UUID NOT NULL REFERENCES schools(id) ON DELETE CASCADE,name VARCHAR(200) NOT NULL,code VARCHAR(80) NOT NULL,address TEXT,phone VARCHAR(40),email VARCHAR(200),logo_url TEXT,is_main BOOLEAN NOT NULL DEFAULT false,status VARCHAR(20) NOT NULL DEFAULT 'active',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(school_id,code));
CREATE UNIQUE INDEX IF NOT EXISTS branches_one_main_idx ON branches(school_id) WHERE is_main;
CREATE TABLE IF NOT EXISTS users(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),school_id UUID REFERENCES schools(id) ON DELETE CASCADE,branch_id UUID REFERENCES branches(id) ON DELETE SET NULL,email VARCHAR(200),phone VARCHAR(40),password_hash TEXT NOT NULL,role VARCHAR(40) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'active',last_login_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(school_id IS NOT NULL OR role='super_admin'));
CREATE UNIQUE INDEX IF NOT EXISTS users_email_unique_idx ON users(lower(email)) WHERE email IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS users_phone_unique_idx ON users(phone) WHERE phone IS NOT NULL;
CREATE TABLE IF NOT EXISTS school_settings(school_id UUID PRIMARY KEY REFERENCES schools(id) ON DELETE CASCADE,display_name VARCHAR(200),logo_url TEXT,primary_color VARCHAR(30),secondary_color VARCHAR(30),address TEXT,phone VARCHAR(40),email VARCHAR(200),website TEXT,timezone VARCHAR(80) DEFAULT 'Asia/Kolkata',currency_code VARCHAR(10) DEFAULT 'INR',locale VARCHAR(20) DEFAULT 'en-IN',date_format VARCHAR(30) DEFAULT 'DD-MM-YYYY',created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS mobile_app_configs(school_id UUID PRIMARY KEY REFERENCES schools(id) ON DELETE CASCADE,app_name VARCHAR(200),app_slug VARCHAR(120) UNIQUE,android_package VARCHAR(200),ios_bundle_id VARCHAR(200),api_base_url TEXT,logo_url TEXT,primary_color VARCHAR(30),secondary_color VARCHAR(30),support_email VARCHAR(200),support_phone VARCHAR(40),min_app_version VARCHAR(30),force_update BOOLEAN DEFAULT false,status VARCHAR(20) DEFAULT 'active',created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS academic_sessions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),school_id UUID NOT NULL REFERENCES schools(id) ON DELETE CASCADE,name VARCHAR(100) NOT NULL,starts_on DATE NOT NULL,ends_on DATE NOT NULL,is_current BOOLEAN DEFAULT false,status VARCHAR(20) DEFAULT 'active',created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now(),UNIQUE(school_id,name),CHECK(starts_on<=ends_on));
CREATE TABLE IF NOT EXISTS classes(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),school_id UUID NOT NULL REFERENCES schools(id) ON DELETE CASCADE,branch_id UUID REFERENCES branches(id) ON DELETE SET NULL,name VARCHAR(100) NOT NULL,code VARCHAR(50),status VARCHAR(20) DEFAULT 'active',created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now(),UNIQUE(school_id,branch_id,name));
CREATE TABLE IF NOT EXISTS sections(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),school_id UUID NOT NULL REFERENCES schools(id) ON DELETE CASCADE,class_id UUID NOT NULL REFERENCES classes(id) ON DELETE CASCADE,name VARCHAR(100) NOT NULL,code VARCHAR(50),status VARCHAR(20) DEFAULT 'active',created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now(),UNIQUE(class_id,name));
CREATE TABLE IF NOT EXISTS subjects(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),school_id UUID NOT NULL REFERENCES schools(id) ON DELETE CASCADE,name VARCHAR(150) NOT NULL,code VARCHAR(50),subject_type VARCHAR(30) DEFAULT 'academic',status VARCHAR(20) DEFAULT 'active',created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now(),UNIQUE(school_id,name));
CREATE TABLE IF NOT EXISTS teachers(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),school_id UUID NOT NULL REFERENCES schools(id) ON DELETE CASCADE,user_id UUID NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE,branch_id UUID REFERENCES branches(id) ON DELETE SET NULL,full_name VARCHAR(200) NOT NULL,employee_code VARCHAR(80),phone VARCHAR(40),email VARCHAR(200),status VARCHAR(20) DEFAULT 'active',created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS parents(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),school_id UUID NOT NULL REFERENCES schools(id) ON DELETE CASCADE,branch_id UUID REFERENCES branches(id) ON DELETE SET NULL,user_id UUID NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE,full_name VARCHAR(200) NOT NULL,phone VARCHAR(40),email VARCHAR(200),status VARCHAR(20) DEFAULT 'active',created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS students(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),school_id UUID NOT NULL REFERENCES schools(id) ON DELETE CASCADE,branch_id UUID REFERENCES branches(id) ON DELETE SET NULL,admission_no VARCHAR(100) NOT NULL,roll_no VARCHAR(50),full_name VARCHAR(200) NOT NULL,date_of_birth DATE,gender VARCHAR(30),photo_url TEXT,admission_date DATE,status VARCHAR(20) DEFAULT 'active',created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now(),UNIQUE(school_id,admission_no));
CREATE TABLE IF NOT EXISTS enrollments(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),school_id UUID NOT NULL REFERENCES schools(id) ON DELETE CASCADE,branch_id UUID REFERENCES branches(id) ON DELETE SET NULL,student_id UUID NOT NULL REFERENCES students(id) ON DELETE CASCADE,session_id UUID NOT NULL REFERENCES academic_sessions(id) ON DELETE CASCADE,section_id UUID NOT NULL REFERENCES sections(id) ON DELETE RESTRICT,class_id UUID,roll_no VARCHAR(50),status VARCHAR(20) DEFAULT 'active',created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now(),UNIQUE(student_id,session_id));
CREATE TABLE IF NOT EXISTS student_portal_profiles(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),school_id UUID NOT NULL REFERENCES schools(id) ON DELETE CASCADE,student_id UUID NOT NULL REFERENCES students(id) ON DELETE CASCADE,user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,relation VARCHAR(40) DEFAULT 'guardian',is_primary BOOLEAN DEFAULT false,status VARCHAR(20) DEFAULT 'active',UNIQUE(student_id,user_id));
CREATE TABLE IF NOT EXISTS exams(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),school_id UUID NOT NULL REFERENCES schools(id) ON DELETE CASCADE,session_id UUID NOT NULL REFERENCES academic_sessions(id) ON DELETE CASCADE,name VARCHAR(160) NOT NULL,exam_type VARCHAR(60),starts_on DATE,ends_on DATE,status VARCHAR(20) DEFAULT 'draft',created_by UUID REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS exam_subjects(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),school_id UUID NOT NULL REFERENCES schools(id) ON DELETE CASCADE,exam_id UUID NOT NULL REFERENCES exams(id) ON DELETE CASCADE,subject_id UUID NOT NULL REFERENCES subjects(id) ON DELETE RESTRICT,class_id UUID NOT NULL REFERENCES classes(id) ON DELETE RESTRICT,branch_id UUID REFERENCES branches(id) ON DELETE SET NULL,max_marks NUMERIC(8,2) DEFAULT 100,pass_marks NUMERIC(8,2),exam_date DATE,status VARCHAR(20) DEFAULT 'active',UNIQUE(exam_id,subject_id,class_id));
CREATE TABLE IF NOT EXISTS exam_marks(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),school_id UUID NOT NULL REFERENCES schools(id) ON DELETE CASCADE,exam_subject_id UUID NOT NULL REFERENCES exam_subjects(id) ON DELETE CASCADE,student_id UUID NOT NULL REFERENCES students(id) ON DELETE CASCADE,marks NUMERIC(8,2) NOT NULL CHECK(marks>=0),grade VARCHAR(20),remarks TEXT,created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now(),UNIQUE(school_id,exam_subject_id,student_id));
CREATE TABLE IF NOT EXISTS audit_logs(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),school_id UUID REFERENCES schools(id) ON DELETE CASCADE,user_id UUID REFERENCES users(id) ON DELETE SET NULL,action VARCHAR(100) NOT NULL,entity_type VARCHAR(100),entity_id UUID,metadata JSONB DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS sync_devices(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),school_id UUID NOT NULL REFERENCES schools(id) ON DELETE CASCADE,device_key VARCHAR(200) NOT NULL,device_name VARCHAR(200),platform VARCHAR(30) DEFAULT 'unknown',last_cursor BIGINT DEFAULT 0,last_seen_at TIMESTAMPTZ,status VARCHAR(20) DEFAULT 'active',created_at TIMESTAMPTZ DEFAULT now(),UNIQUE(school_id,device_key));
CREATE TABLE IF NOT EXISTS sync_changes(cursor BIGSERIAL PRIMARY KEY,school_id UUID NOT NULL REFERENCES schools(id) ON DELETE CASCADE,device_id UUID REFERENCES sync_devices(id) ON DELETE SET NULL,client_change_id VARCHAR(200),base_cursor BIGINT DEFAULT 0,entity_type VARCHAR(100) NOT NULL,entity_id UUID,operation VARCHAR(30) DEFAULT 'update',payload JSONB DEFAULT '{}'::jsonb,changed_by UUID REFERENCES users(id) ON DELETE SET NULL,changed_at TIMESTAMPTZ DEFAULT now());
CREATE INDEX IF NOT EXISTS sync_changes_school_cursor_idx ON sync_changes(school_id,cursor);
CREATE UNIQUE INDEX IF NOT EXISTS sync_changes_device_client_base_idx ON sync_changes(school_id,device_id,client_change_id) WHERE client_change_id IS NOT NULL;
CREATE OR REPLACE FUNCTION touch_updated_at() RETURNS TRIGGER LANGUAGE plpgsql AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END; $$;
